('e7f53941-86a0-4352-87f5-234208a00001', 'ceylon-royal-blue-sapphire-tear-of-serendib-4-15ct', 'Ceylon Royal Blue Sapphire ''Tear of Serendib''', 'Royal Blue Sapphire', 4.15, 'Ratnapura (City of Gems)', 'Pear / Teardrop', '11.20 x 7.80 x 5.60 mm', 'Vivid Royal Blue', 'None / Unheated (Certified 100% Natural)', 'Eye Clean / VVS1', 22800.00, 'USD', true, true, 'A monumental Ceylon royal blue sapphire mined from the alluvial gravels of Kalu Ganga, Ratnapura. Displays velvety blue saturation with intense scintillation and zero thermal treatment.', 'GRS & NGJA', 'GRS2024-089921', null, '[{"url":"/isuru_images/natural%20heart.webp","alt":"4.15ct Ceylon Royal Blue Sapphire Tear of Serendib"},{"url":"/isuru_images/blue1.webp","alt":"Facet brilliance under daylight"}]'::jsonb),
('e7f53941-86a0-4352-87f5-234208a00002', 'ceylon-padparadscha-sapphire-lotus-blossom-3-15ct', 'Ceylon Padparadscha Sapphire (Lotus Blossom)', 'Padparadscha Sapphire', 3.15, 'Pelmadulla, Sri Lanka', 'Oval Mixed Cut', '8.75 x 7.10 x 5.22 mm', 'Sunset Salmon Pink-Orange', 'None / Unheated (100% Natural)', 'Eye Clean / VS1', 24000.00, 'USD', true, true, 'A breathtaking natural Ceylon Padparadscha capturing the exact equilibrium between soft lotus petal pink and sunset gold. Completely unheated with Swiss SSEF certification.', 'SSEF & NGJA', 'SSEF-118492', null, '[{"url":"/isuru_images/Padparadscha%20Sapphire.webp","alt":"3.15ct Ceylon Padparadscha Sapphire"}]'::jsonb),
