('e7f53941-86a0-4352-87f5-234208a00005', 'natural-ceylon-pigeon-blood-ruby-2-05ct', 'Natural Ceylon Ruby (Pigeon Blood Glow)', 'Ceylon Ruby', 2.05, 'Pelmadulla, Sri Lanka', 'Cushion Brilliant', '7.60 x 6.55 x 4.80 mm', 'Vibrant Crimson Pink-Red', 'None / Unheated (Natural Fluorescence)', 'Eye Clean / VS1', 16200.00, 'USD', true, true, 'Sourced from the deep gravels of Pelmadulla. Celebrated for high chromium content giving intense internal scarlet luminescence and natural fluorescence under daylight.', 'GRS Certified', 'GRS-RUB-88412', null, '[{"url":"/isuru_images/Natural%20Ruby.webp","alt":"2.05ct Natural Ceylon Ruby Cushion"},{"url":"/isuru_images/ruby%20category.webp","alt":"Ceylon Ruby table reflection"}]'::jsonb),
('e7f53941-86a0-4352-87f5-234208a00006', 'ceylon-golden-pushparaga-yellow-sapphire-5-60ct', 'Ceylon Golden Pushparaga (Yellow Sapphire)', 'Yellow Sapphire (Pushparaga)', 5.6, 'Balangoda, Sri Lanka', 'Emerald Cut', '11.20 x 8.45 x 6.10 mm', 'Imperial Honey Gold', 'None / Unheated', 'Eye Clean / Flawless', 11400.00, 'USD', true, true, 'Revered in Vedic gemology as Pushparaga for auspicious fortune. Cut in a stately emerald step profile with fiery amber brilliance from the decomposed granite gravels of Balangoda.', 'NGJA Certified', 'NGJA-2024-C9081', null, '[{"url":"/isuru_images/yellow.webp","alt":"5.60ct Ceylon Golden Pushparaga Emerald Cut"}]'::jsonb),
